```python
def _least_rotation(seq):
    """Return the start index of the lexicographically smallest rotation."""
    n = len(seq)
    if n <= 1:
        return 0

    s = seq + seq
    i, j, k = 0, 1, 0

    while i < n and j < n and k < n:
        a = s[i + k]
        b = s[j + k]
        if a == b:
            k += 1
        elif a > b:
            i += k + 1
            if i == j:
                j += 1
            k = 0
        else:
            j += k + 1
            if i == j:
                j += 1
            k = 0

    return i if i < j else j


def _primitive_period(seq):
    """Smallest p dividing len(seq) such that seq has cyclic period p."""
    n = len(seq)
    if n == 0:
        return 0
    if n == 1:
        return 1

    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        x = seq[i]
        while j and x != seq[j]:
            j = pi[j - 1]
        if x == seq[j]:
            j += 1
        pi[i] = j

    p = n - pi[-1]
    return p if n % p == 0 else n


def group_rings(rings: list[list[int]]) -> list[tuple[int, list[int]]]:
    groups = {}

    for idx, ring in enumerate(rings):
        n = len(ring)

        if n == 0:
            key = (0, ())
            period = 0
        else:
            period = _primitive_period(ring)

            if period == n:
                r = _least_rotation(ring)
                if r:
                    canonical = ring[r:] + ring[:r]
                else:
                    canonical = ring
                key = (n, tuple(canonical))
            else:
                block = ring[:period]
                r = _least_rotation(block)
                if r:
                    canonical_block = block[r:] + block[:r]
                else:
                    canonical_block = block
                key = (n, tuple(canonical_block))

        entry = groups.get(key)
        if entry is None:
            groups[key] = (period, [idx])
        else:
            entry[1].append(idx)

    return sorted(groups.values(), key=lambda item: item[1][0])
```

