def least_rotation(S):
    S = S + S
    f = [-1]*len(S)
    k = 0
    for j in range(1, len(S)):
        i = f[j-k-1]
        while i >= 0 and S[j] != S[k+i+1]:
            if S[j] < S[k+i+1]:
                k = j - i - 1
            i = f[i]
        if i < 0 and S[j] != S[k+i+1]:
            if S[j] < S[k+i+1]:
                k = j
        f[j] = i+1
