```
def minimal_period(seq):
    n = len(seq)
    if n == 0: return 0
    pi = [0] * n
    for i in range(1, n):
        j = pi[i-1]
        while j and seq[i] != seq[j]:
            j = pi[j-1]
        if seq[i] == seq[j]:
            j += 1
        pi[i] = j
    p = n - pi[-1]
    if n % p == 0:
        return p
    return n
```
